.venv/bin/python - <<'PY'
import glob,time,serial
ports=sorted(set(glob.glob('/dev/cu.usbserial-*')))
for port in ports:
    text=''
    try:
        with serial.Serial(port,115200,timeout=.08,write_timeout=1) as h:
            try: h.dtr=False; h.rts=False
            except Exception: pass
            time.sleep(.5); h.reset_input_buffer(); h.write(b'status\n'); h.flush()
            end=time.monotonic()+2.5
            while time.monotonic()<end:
                b=h.read(4096)
                if b: text += b.decode(errors='replace')
        hits=[ln.strip() for ln in text.splitlines() if 'firmware_sha=' in ln or 'outputs=' in ln or 'rf_ready=' in ln]
        print(f'PORT_PROBE port={port} bytes={len(text)} hits={len(hits)}')
        for ln in hits[:8]: print('PORT_LINE '+port+' '+ln[:1000])
    except Exception as e:
        print(f'PORT_PROBE_ERROR port={port} error={type(e).__name__}:{e}')
PY
